  ('inv-t-05', 'invent', 'text', 'after', 'open', 1, 14, null, 'Continue this story: The letter was addressed to someone who had never lived there.', 'draft'),
  ('inv-t-06', 'invent', 'text', 'after', 'open', 1, 17, null, 'Continue this story: Halfway up the mountain, the guide admitted he had never been this way before.', 'draft'),
